-- These helpers exist only in the disposable database, not migrations.
create function public.test_assert(ok boolean,label text) returns void language plpgsql as $$begin if ok is distinct from true then raise exception 'Assertion failed: %',label; end if; raise notice 'PASS %',label; end$$;
create function public.test_error(statement text,expected text,label text) returns void language plpgsql as $$begin
 begin execute statement; exception when others then if sqlstate=expected then raise notice 'PASS %',label; return; end if; raise; end;
 raise exception 'Expected SQLSTATE %: %',expected,label;
end$$;
create function public.test_vector(x float8,y float8 default 0) returns extensions.vector language sql as $$select (array[x,y]||array_fill(0.0,array[1534]))::extensions.vector(1536)$$;
grant execute on function public.test_assert(boolean,text),public.test_error(text,text,text),public.test_vector(float8,float8) to anon,authenticated,service_role;
set role service_role;
select public.test_assert(public.backend_contract_version()=1,'schema bootstrap');
select public.test_assert((select count(*)=5 from public.document_versions),'synthetic immutable versions');
select public.test_assert((select count(*)=0 from public.pending_embedding_documents('synthetic-basis-1536','basis-v1','paragraph-v1')),'unchanged corpus does not re-embed');
select public.test_assert((select count(*)=5 from public.pending_embedding_documents('different-model','v2','paragraph-v1')),'embedding version invalidates selection');
select public.test_error($q$insert into public.matches(id,home_team_id,away_team_id,venue_id,kickoff_at) values('bad','missing','harbor','test-ground',now())$q$,'23503','foreign key enforcement');
select public.test_error($q$insert into public.teams(id,name) values('maple','Duplicate')$q$,'23505','primary key enforcement');
insert into public.teams(id,name,external_provider,external_id) values('synthetic-upsert','Test Upsert','wcl-synthetic','1') on conflict(id) do update set name=excluded.name;
insert into public.teams(id,name,external_provider,external_id) values('synthetic-upsert','Test Upsert','wcl-synthetic','1') on conflict(id) do update set name=excluded.name;
select public.test_assert((select count(*)=1 from public.teams where id='synthetic-upsert'),'idempotent fixture upsert');
select public.test_error($q$insert into public.teams(id,name,external_provider,external_id) values('duplicate-external','Duplicate','wcl-synthetic','1')$q$,'23505','provider identity uniqueness');
select public.test_error($q$insert into public.teams(id,name,data_origin,publication_status) values('bad-publication','No','provider','synthetic-public')$q$,'23514','provider publication denied');
select public.test_error($q$update public.documents set availability_verified=true where published_at is null$q$,'23514','unknown temporal metadata fails closed');
select public.test_error($q$update public.documents set availability_evidence=null where availability_verified$q$,'23514','missing evidence fails closed');
select public.test_error($q$insert into public.document_chunks(document_id,chunk_index,content,embedding) values('00000000-0000-4000-8000-000000000001',999,'Test','[1,0]')$q$,'22000','vector dimensions');
select public.test_error($q$select * from public.match_document_chunks(public.test_vector(0))$q$,'22023','zero query vector');
select public.test_error($q$select * from public.match_document_chunks(public.test_vector(1),0,51)$q$,'22023','bounded match count');
select public.test_error($q$select * from public.match_document_chunks(public.test_vector(1),'NaN',8)$q$,'22023','invalid threshold');
select public.test_assert((select count(*)=4 from public.match_document_chunks(public.test_vector(1),.15,8,array['maple','harbor'],'test-ground','synthetic-match',null,'synthetic-basis-1536','basis-v1')),'entity filters exclude another match despite shared team');
select public.test_assert((select count(*)=2 from public.match_document_chunks(public.test_vector(1),.15,8,array['maple','harbor'],'test-ground','synthetic-match','2026-07-10Z','synthetic-basis-1536','basis-v1')),'cutoff excludes unknown and later capture');
select public.test_assert((select count(*)=1 from public.match_document_chunks(public.test_vector(1),.15,8,null,null,null,null,'synthetic-basis-1536','basis-v1')),'only explicitly global sources without requested entities');
select public.test_assert((select count(*)=0 from public.match_document_chunks(public.test_vector(-1),.15,8,array['maple'],'test-ground','synthetic-match',null,'synthetic-basis-1536','basis-v1')),'threshold filters opposite vector');
select public.test_assert((select count(*)=0 from public.match_document_chunks(public.test_vector(1),.15,8,array['maple'],'test-ground','synthetic-match',null,'different','basis-v1')),'model isolation');
select public.test_assert((select array_agg(id)=array_agg(id order by id) from public.match_document_chunks(public.test_vector(1),.15,8,array['maple','harbor'],'test-ground','synthetic-match',null,'synthetic-basis-1536','basis-v1')),'deterministic ID tie-break');
select public.test_assert((select count(*)=1 from public.match_document_chunks(public.test_vector(1),.15,1,array['maple','harbor'],'test-ground','synthetic-match',null,'synthetic-basis-1536','basis-v1')),'match count limit');
begin;
update public.documents set body=body||' Later unreviewed content.' where id='00000000-0000-4000-8000-000000000001';
select public.test_assert((select not availability_verified and availability_evidence is null from public.documents where id='00000000-0000-4000-8000-000000000001'),'source edits invalidate old availability attestation');
select public.test_assert((select count(*)=1 from public.match_document_chunks(public.test_vector(1),.15,8,array['maple','harbor'],'test-ground','synthetic-match','2026-07-10Z','synthetic-basis-1536','basis-v1')),'modified content cannot inherit historical eligibility');
rollback;
select public.test_error($q$update public.document_versions set title='Changed'$q$,'42501','privileged history update denied');
select public.test_error($q$delete from public.document_chunks$q$,'42501','privileged chunk deletion denied');
-- A malformed batch must roll back new version, chunks and pointer together.
select public.test_error($q$select public.store_document_revision(id,input_hash,'synthetic-basis-1536','bad-v2','synthetic','paragraph-v1',clock_timestamp(),clock_timestamp(),jsonb_build_array(jsonb_build_object('content',body,'metadata','{}'::jsonb,'embedding','[1,0]'::jsonb))) from public.documents where id='00000000-0000-4000-8000-000000000001'$q$,'22000','partial revision rollback');
select public.test_assert((select count(*)=5 from public.document_versions),'failed revision preserves history');
select public.test_assert((select count(*)=5 from public.document_chunks),'failed revision preserves chunks');
select public.test_error($q$select public.store_document_revision(id,'stale','synthetic-basis-1536','basis-v1','synthetic','paragraph-v1',clock_timestamp(),clock_timestamp(),'[]') from public.documents limit 1$q$,'40001','stale document snapshot rejected');
reset role;
create function public.test_lens() returns jsonb language sql as $$select '{"headline":"A fictional matchup for the integration corpus.","slightEdge":null,"confidence":"Low","volatility":"Medium","expectedGame":"The source provides no measured performance comparison.","whyItMatters":"This original synthetic example tests the authoring pipeline safely.","likelyGameScript":"The evidence does not establish how this fictional match will unfold.","teamEdges":[],"whatToWatch":["Source availability","Document identity","Cache versioning"],"casualFanGuide":"Read this as fictional commentary, not a historical football forecast.","uncertainty":["No player data is supplied.","The scenario is entirely synthetic."],"sources":[{"title":"Maple synthetic profile","snippet":"Maple Eleven is an original fictional team."}]}'::jsonb$$;
create function public.test_payload(cutoff timestamptz default null) returns jsonb language plpgsql as $$declare ctx jsonb;i jsonb; t timestamptz:=clock_timestamp(); begin
 select coalesce(jsonb_agg(to_jsonb(r)-'content' order by r.similarity desc,r.id),'[]'::jsonb) into ctx from public.match_document_chunks(public.test_vector(1),.15,8,array['maple','harbor'],'test-ground','synthetic-match',cutoff,'synthetic-basis-1536','basis-v1') r;
 i:=jsonb_build_object('contractVersion',1,'matchId','synthetic-match','inputFingerprint',public.authoring_input_fingerprint('synthetic-match'),'datasetVersion','synthetic-v1','perspective',case when cutoff is null then 'retrospective' else 'as-of' end,'historicalCutoff',cutoff,'inputAttestation',(select jsonb_build_object('inputFingerprint',a.input_fingerprint,'availableAt',a.available_at,'evidence',a.evidence) from public.authoring_input_attestations a where a.match_id='synthetic-match' and a.input_fingerprint=public.authoring_input_fingerprint('synthetic-match')),'model','deterministic-mock','generatorKind','mock','promptVersion','evidence-only-v1','schemaVersion','qualitative-lens-v1','embeddingModel','synthetic-basis-1536','embeddingVersion','basis-v1','queryEmbedding',to_jsonb(public.test_vector(1)::text)::jsonb,'threshold',.15,'count',8,'context',ctx);
 -- vector::text is a JSON string; identity needs the array itself.
 i:=jsonb_set(i,'{queryEmbedding}',(public.test_vector(1)::text)::jsonb);
 return jsonb_build_object('id',gen_random_uuid(),'identityCanonical',i::text,'retrievedAt',t,'startedAt',t,'completedAt',clock_timestamp(),'status','succeeded','lens',public.test_lens(),'errorCode',null);
end$$;
grant execute on function public.test_payload(timestamptz),public.test_lens() to service_role;
set role service_role;
select public.test_assert(public.valid_lens_json(public.test_lens()),'valid SQL final Lens shape');
select public.test_assert(not public.valid_lens_json('{"confidence":"Low","volatility":"Low","teamEdges":[]}'),'incomplete SQL Lens shape denied');
create temporary table checkpoint as select public.test_payload() as payload;
select public.commit_lens_generation(payload) from checkpoint;
select public.commit_lens_generation(payload) from checkpoint;
select public.test_assert((select count(*)=1 from public.generation_runs),'idempotent persistence retry');
select public.test_assert((select count(*)=4 from public.generation_run_chunks),'immutable retrieved chunk identities');
select public.test_assert((select count(*)=1 from public.lens_cache_entries),'versioned cache entry');
select public.test_assert((select generation_id is not null from public.match_lenses where match_id='synthetic-match'),'legacy retrospective cache adapter');
select public.test_error($q$update public.generation_runs set status='failed'$q$,'42501','generation history update denied');
select public.test_error($q$delete from public.lens_cache_entries$q$,'42501','cache history deletion denied');
select public.test_error($q$select public.commit_lens_generation(jsonb_set(payload,'{lens,confidence}','"Certain"')) from checkpoint$q$,'23505','generation identity cannot mutate');
select public.test_error($q$select public.commit_lens_generation(jsonb_set(public.test_payload(),'{lens,confidence}','"Certain"'))$q$,'22023','invalid final enum denied');
select public.test_error($q$select public.commit_lens_generation(public.test_payload('2026-07-10Z'))$q$,'22023','as-of without exact snapshot attestation denied');
insert into public.authoring_input_attestations(match_id,input_fingerprint,available_at,evidence) values('synthetic-match',public.authoring_input_fingerprint('synthetic-match'),'2026-07-02Z','Fictional availability test, not real forecast evidence');
select public.commit_lens_generation(public.test_payload('2026-07-10Z'));
select public.test_assert((select count(*)=2 from public.generation_runs),'attested synthetic as-of record preserved separately');
update public.teams set name='Maple Eleven revised' where id='maple';
select public.test_error($q$select public.commit_lens_generation(public.test_payload('2026-07-10Z'))$q$,'22023','changed team invalidates historical input attestation');
select public.test_error($q$select public.commit_lens_generation(jsonb_set(payload,'{id}',to_jsonb(gen_random_uuid()))) from checkpoint$q$,'40001','stale match fingerprint denied');
update public.teams set name='Maple Eleven' where id='maple';
create temporary table stale_source as select public.test_payload() as payload;
update public.documents set source_provider='revised attribution' where id='00000000-0000-4000-8000-000000000001';
select public.test_error($q$select public.commit_lens_generation(payload) from stale_source$q$,'40001','stale retrieval denied');
select public.test_assert((select count(*)=1 from public.pending_embedding_documents('synthetic-basis-1536','basis-v1','paragraph-v1')),'changed metadata invalidates document embedding');
select public.test_assert((select count(*)=3 from public.match_document_chunks(public.test_vector(1),.15,8,array['maple','harbor'],'test-ground','synthetic-match',null,'synthetic-basis-1536','basis-v1')),'outdated chunks excluded before re-embedding');
select public.store_document_revision(id,input_hash,'synthetic-basis-1536','basis-v1','synthetic','paragraph-v1',clock_timestamp(),clock_timestamp(),jsonb_build_array(jsonb_build_object('content',body,'metadata','{}'::jsonb,'embedding',(public.test_vector(0,1)::text)::jsonb))) from public.documents where id='00000000-0000-4000-8000-000000000001';
select public.test_assert((select count(*)=6 from public.document_versions),'new document revision preserves old version');
select public.test_assert((select not availability_verified and availability_evidence is null from public.documents where id='00000000-0000-4000-8000-000000000001'),'edited source retains no old availability evidence after re-embedding');
select public.test_assert((select count(*)=0 from public.match_document_chunks(public.test_vector(0,1),.15,8,array['maple','harbor'],'test-ground','synthetic-match','2026-07-10Z','synthetic-basis-1536','basis-v1')),'re-embedded source cannot recover revoked historical eligibility');

select public.test_assert((select source_provider='revised attribution' from public.document_versions where id=(select current_version_id from public.documents where id='00000000-0000-4000-8000-000000000001')),'source provider retained in immutable version');
select public.test_assert((select similarity=0 from public.match_document_chunks(public.test_vector(1),0,8,array['maple','harbor'],'test-ground','synthetic-match',null,'synthetic-basis-1536','basis-v1') where document_id='00000000-0000-4000-8000-000000000001'),'cosine similarity and threshold boundary');
select public.commit_lens_generation(public.test_payload());
select public.test_assert((select count(*)=3 from public.lens_cache_entries),'changed source changes cache identity');
-- Failed generation append does not replace successful cache pointers.
select public.commit_lens_generation(public.test_payload()||jsonb_build_object('status','failed','lens',null,'errorCode','generation-failed'));
select public.test_assert((select count(*)=3 from public.lens_cache_entries),'failed generation leaves cache intact');
update public.match_lenses set data_origin='synthetic',publication_status='synthetic-public' where match_id='synthetic-match';
reset role;
set role anon;
select public.test_assert((select count(*)=2 from public.teams),'public synthetic teams only');
select public.test_assert((select count(*)=1 from public.matches),'public synthetic matches only');
select public.test_assert((select count(*)=1 from public.match_lenses),'public reviewed synthetic cache read');
select public.test_assert((select count(*)=1 from public.qa_answers),'public synthetic Q&A read');
select public.test_error('select * from public.documents','42501','anonymous source read denied');
select public.test_error('select * from public.document_chunks','42501','anonymous vector read denied');
select public.test_error('select * from public.generation_runs','42501','anonymous lineage read denied');
select public.test_error($q$insert into public.teams(id,name) values('intruder','No')$q$,'42501','anonymous write denied');
select public.test_error($q$select * from public.match_document_chunks(public.test_vector(1))$q$,'42501','anonymous RPC denied');
reset role;
set role authenticated;
select public.test_error('select * from public.documents','42501','authenticated source read denied');
select public.test_error($q$delete from public.matches$q$,'42501','authenticated writes denied');
reset role;
select public.test_error($q$update public.generation_runs set status='failed'$q$,'55000','immutable trigger even for owner');
select public.test_error($q$delete from public.document_versions$q$,'55000','immutable source version trigger');
select public.test_assert((select count(*)>=4 from public.generation_runs),'all successful and failed attempts retained');

select public.test_assert(not has_function_privilege('anon','public.match_document_chunks(extensions.vector,double precision,integer,text[],text,text,timestamp with time zone,text,text)','EXECUTE'),'explicit RPC execution privilege');
select public.test_assert(not has_table_privilege('anon','public.documents','SELECT'),'explicit source table privilege');
select public.test_error($q$insert into public.document_chunks(document_id,chunk_index,content,embedding,metadata) values('00000000-0000-4000-8000-000000000001',999,'Synthetic content',public.test_vector(1),'[]')$q$,'23514','malformed chunk metadata');
select public.test_assert((select count(*)=0 from public.match_document_chunks(public.test_vector(1),.15,8,array['maple','harbor'],'test-ground','synthetic-match','2026-06-01Z','synthetic-basis-1536','basis-v1')),'empty historical retrieval');
do $$declare p jsonb; i jsonb; before_count bigint; begin
 p:=public.test_payload();i:=(p->>'identityCanonical')::jsonb;
 i:=jsonb_set(jsonb_set(i,'{queryEmbedding}',(public.test_vector(-1)::text)::jsonb),'{context}','[]');
 p:=p||jsonb_build_object('identityCanonical',i::text,'status','failed','lens',null,'startedAt',null,'completedAt',null,'errorCode','empty-context');
 select count(*) into before_count from public.lens_cache_entries;
 perform public.commit_lens_generation(p);
 perform public.test_assert((select count(*)=before_count from public.lens_cache_entries),'empty context never advances cache');
 perform public.test_assert((select generation_started_at is null from public.generation_runs where id=(p->>'id')::uuid),'no fabricated empty-context generation clock');
end$$;
select public.test_assert((select public.get_cached_lens(cache_key) is not null from public.lens_cache_entries limit 1),'versioned cache read RPC');

create function public.test_fail_cache() returns trigger language plpgsql as $$begin raise exception 'Synthetic persistence fault' using errcode='40001';end$$;
create trigger test_injected_failure before insert on public.lens_cache_entries for each row execute function public.test_fail_cache();
create temporary table before_fault as select count(*) as runs from public.generation_runs;
select public.test_error($q$select public.commit_lens_generation(jsonb_set(public.test_payload(),'{identityCanonical}',to_jsonb(jsonb_set((public.test_payload()->>'identityCanonical')::jsonb,'{datasetVersion}','"synthetic-fault-v1"')::text)))$q$,'40001','failure after run insertion rolls back entire commit');
select public.test_assert((select count(*)=(select runs from before_fault) from public.generation_runs),'partial persistence leaves no orphan generation');
drop trigger test_injected_failure on public.lens_cache_entries;
drop function public.test_fail_cache();
-- Concurrent retry fixtures are queried only by the local runner, then destroyed with the cluster.
create table public.test_concurrency as select public.test_payload() as payload;
grant select on public.test_concurrency to service_role;
